import { z } from 'zod';

/**
 * A node in the page tree. `component` is either an antd component name
 * (e.g. "Button", "Form.Item") or the id of a custom component generated by the LLM.
 */
export interface BuilderNode {
  id: string;
  component: string;
  props: Record<string, unknown>;
  children: BuilderNode[];
}

export const builderNodeSchema: z.ZodType<BuilderNode> = z.lazy(() =>
  z.object({
    id: z.string(),
    component: z.string(),
    props: z.record(z.string(), z.unknown()),
    children: z.array(builderNodeSchema),
  }),
);

/** A custom (non-standard) component, generated by the LLM and stored with the project. */
export const customComponentSchema = z.object({
  id: z.string(),
  name: z.string(),
  description: z.string(),
  /** TSX source; must default-export a React component built from antd primitives. */
  source: z.string(),
  /** JSON schema of the props, so the editor can render a props panel. */
  propsSchema: z.record(z.string(), z.unknown()),
});
export type CustomComponent = z.infer<typeof customComponentSchema>;

export const pageSchema = z.object({
  id: z.string(),
  name: z.string(),
  root: builderNodeSchema,
});
export type Page = z.infer<typeof pageSchema>;

export const projectSchema = z.object({
  version: z.literal(1),
  name: z.string(),
  /** antd ThemeConfig (tokens, algorithm, component overrides). */
  theme: z.record(z.string(), z.unknown()),
  pages: z.array(pageSchema),
  customComponents: z.array(customComponentSchema),
});
export type Project = z.infer<typeof projectSchema>;
